import pandas as pd

def clean(df):
    df = df.copy()
    # Strip stray whitespace in text columns (fixes 'female ' -> 'female')
    for col in ['penguin_id', 'species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].apply(lambda v: v.strip() if isinstance(v, str) else v)
    # Fix island label variant 'Bisco' -> 'Biscoe'
    df['island'] = df['island'].replace({'Bisco': 'Biscoe'})
    # Ensure numeric columns are numeric (some values may be stored as text)
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # Drop exact duplicate rows (keep first occurrence), preserving the id column
    df = df.drop_duplicates(keep='first').reset_index(drop=True)
    return df

def answer(df):
    df = clean(df)
    # sex is missing for one row: do not guess, drop missing group keys
    d = df[df['sex'].notna()]
    d = d[d['body_mass_g'].notna()]
    grouped = d.groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in grouped.items()}
